 Here's an example of creating a professional access permissions guard using Nest.js and TypeORM for user roles with a sample list of permissions:

```javascript
import { Injectable, CanActivate, ExecutionContext } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { JwtAuthGuard } from './jwt-auth.guard'; // Assuming JWT authentication is implemented in jwt-auth.guard
import { UserRoleEnum } from './user.enum'; // Define user roles enum
import { Repository } from 'typeorm';
import { User } from './user.entity'; // User entity

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(
    private reflector: Reflector,
    private userRepository: Repository<User>,
  ) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const roles = this.reflector.get<UserRoleEnum[]>('roles', context.getHandler());
    const req = context.switchToHttp().getRequest();
    const user = await this.userRepository.findOne({ where: { id: req.user.id } });

    if (!user) {
      throw new UnauthorizedException();
    }

    return (roles && roles.some((role) => user.role === role)) || this.checkAdmin(user);
  }

  private checkAdmin(user: User): boolean {
    return user.role === UserRoleEnum.ADMIN;
  }
}

// Sample route decorator usage
@UseGuards(JwtAuthGuard, RolesGuard)
@Controller('admin')
export class AdminController {}

// Permissions array example
export const permissions = ['admin', 'moderator', 'user'];
```

Replace `UserRoleEnum`, `User`, and `UserEntity` with your actual types. This example sets up a custom guard that checks the user's role against provided roles. You can use `@Roles()` decorator to define roles for specific routes. Make sure you have a working JWT authentication setup.

