            display: none;
        }

        .container {
            text-align: center;
            width: 100%;
            height: 100vh;
            background-size: cover;
            background-position: center;
        }
    </style>
</head>
<body>
    <button onclick="showFileInput()" id="changeBackground">Change Background Image</button>
    <input type="file" id="imageInput" accept="image/*" onchange="handleImage(event)">
    <div class="container" id="background"></div>

    <script>
        function showFileInput() {
            document.getElementById('imageInput').click();
        }

        function handleImage(event) {
            const file = event.target.files[0];
            const reader = new FileReader();

            reader.onload = function () {
                const img = new Image();
                img.src = reader.result;
                img.onload = function () {
                    document.getElementById('background').style.backgroundImage = `url(${img.src})`;
                };
            };

            reader.readAsDataURL(file);
        }
    </script>
</body>
</html>
```

