using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class AudioVisualizer : MonoBehaviour
{
    public GameObject particleSystemPrefab; // Drag & drop your ParticleSystem prefab here
    public AudioSource audioSource;

    private float[] samples = new float[64];
    private ParticleSystem particleSystem;

    void Start()
    {
        if (particleSystemPrefab == null) return;
        particleSystem = Instantiate(particleSystemPrefab).GetComponent<ParticleSystem>();
        Destroy(gameObject.GetComponent<MeshFilter>()); // Remove mesh to allow ParticleSystem to be parented
        particleSystem.transform.parent = transform;
    }

    void Update()
    {
        if (!audioSource.isPlaying) return;

        int samplesSize = audioSource.GetSpectrumData(samples, 0, FFTWindow.BlackmanHarris);

        if (particleSystem != null)
            particleSystem.Emit(samplesSize);
    }
}
```

