```matlab
% Initialize population size, number of generations, and other parameters
population_size = 100;
num_generations = 50;
selection_pressure = 0.5; % Probability of selecting individuals with advantageous trait (A)
mutation_rate = 0.01; % Probability of mutating a gene per individual per generation
% Initialize random initial population
population = randi(2, population_size, 1); % 0 or 1 for each individual
% Natural selection simulation
for gen = 1:num_generations
    % Calculate fitness based on the selection pressure
    fitness = zeros(population_size, 1);
    fitness(population == 1) = selection_pressure; % Fitness of individuals with trait A
    fitness(population == 0) = 1 - selection_pressure; % Fitness of individuals without trait A

    % Selection: Roulette wheel selection based on fitness proportions
    roulette = cumsum(fitness) / sum(fitness);
    indices = randsample(1:population_size, population_size, true, roulette);
    selected_population = population(indices);

    % Mutation: Randomly mutate a small fraction of genes
    mutated_population = copy(selected_population);
    mutations = randi(2, population_size, 1) < mutation_rate;
    mutated_population(mutations) = 1 - mutated_population(mutations);

    % Replace old population with new one
    population = mutated_population;
end
% Display final population distribution
disp(['Generation ', num2str(num_generations), ':']);
histogram(population, 'Normalization', 'probability');
title('Final Population Distribution');
xlabel('Trait A');
ylabel('Frequency');
```
