 To create a simple toast notification using React and the useContextHook, follow these steps:

First, let's create a custom ToastContext provider and a ToastProvider component.

1. Create a new file named `ToastContext.js`:

```javascript
import { createContext } from 'react';

export const ToastContext = createContext();

export const ToastProvider = ({ children }) => {
  const [toasts, setToasts] = React.useState([]);

  const addToast = (message, type = 'info') => {
    setToasts([...toasts, { message, type }]);
    setTimeout(() => {
      setToasts(toasts.filter((t) => t !== { message, type }));
    }, 3000);
  };

  return (
    <ToastContext.Provider value={{ addToast }}>{children}</ToastContext.Provider>
  );
};
```

2. Import and use the ToastProvider in your main App component or any other parent component:

```javascript
import React from 'react';
import { StrictMode, Suspense } from 'react';
import { ToastProvider } from './ToastContext'; // Import the ToastProvider

function App() {
  return (
    <ToastProvider>
      <StrictMode>
        <Suspense fallback={<div>Loading...</div>}>YourComponent</Suspense>
      </StrictMode>
    </ToastProvider>
  );
}

export default App;
```

3. Create a custom Toast component and consume the ToastContext:

```javascript
// In a new file named Toast.js
import React from 'react';
import { useContext } from 'react';
import { ToastContext } from './ToastContext';

const Toast = () => {
  const { addToast } = useContext(ToastContext);

  const handleClick = () => {
    addToast('This is an info toast!');
  };

  return (
    <button onClick={handleClick}>
      Show Info Toast
    </button>
  );

 Certainly! Here are four methods using the MediaDevices API to handle opening, closing, and checking the status of both the camera and microphone in JavaScript:

1. Opening and Closing Camera and Microphone

```javascript
async function startMediaStream(deviceType) {
  let stream;
  try {
    const constraints = deviceType === 'camera' ? { video: true } : { audio: true };
    stream = await navigator.mediaDevices.getUserMedia(constraints);
  } catch (error) {
    console.error('Error accessing media devices.', error);
  }

  return stream;
}

async function stopMediaStream(stream) {
  try {
    await stream.getTracks().forEach((track) => track.stop());
  } catch (error) {
    console.error('Error stopping media stream.', error);
  }
}
```

2. Checking the Status of Camera and Microphone

```javascript
function checkMediaDeviceAvailability(deviceType) {
  navigator.mediaDevices.enumerateDevices()
    .then((devices) => {
      const device = devices.find((device) => device.kind === deviceType);
      if (device) {
        console.log(`${deviceType} available: ${device.label}`);
      } else {
        console.error(`No ${deviceType} found.`);
      }
    })
    .catch((error) => console.error('Error retrieving media devices.', error));
}
```

3. Opening and Closing Camera and Microphone with Promises

```javascript
async function startMediaStreamPromise(deviceType) {
  try {
    const constraints = deviceType === 'camera' ? { video: true } : { audio: true };
    const stream = await new Promise((resolve, reject) => {
      navigator.mediaDevices.getUserMedia(constraints)
        .then((stream) => resolve(stream))
        .catch((error) => reject(error));
    });
    return stream;
  } catch (error) {
    console.error('Error accessing media devices.', error);
  }
}

