 Here's the code you can use to create the `RedisClient` class in a `redis.js` file inside the `utils` folder:

```javascript
const redis = require('redis');

class RedisClient {
  constructor() {
    this.client = new redis();

    this.client.on('error', (err) => {
      console.error(`Error connecting to Redis: ${err}`);
    });
  }

  isAlive() {
    return this.client.connected;
  }

  async get(key) {
    return new Promise((resolve, reject) => {
      this.client.get(key, (err, value) => {
        if (err) {
          return reject(err);
        }

        resolve(value);
      });
    });
  }

  async set(key, value, duration) {
    return new Promise((resolve, reject) => {
      this.client.set(key, value, 'EX', duration, (err, reply) => {
        if (err) {
          return reject(err);
        }

        resolve(reply);
      });
    });
  }

  async del(key) {
    return new Promise((resolve, reject) => {
      this.client.del(key, (err, result) => {
        if (err) {
          return reject(err);
        }

        resolve(result);
      });
    });
  }
}

const redisClient = new RedisClient();
module.exports = redisClient;
```

This code defines the `RedisClient` class with the required methods and exports an instance of it named `redisClient`. The constructor sets up an event listener for errors and initializes a new Redis client. Each method is defined as an asynchronous function using Promises, and any errors during the execution of these methods are rejected with a Promise rejection.

